# Estado por usuario
user_state = {}

def buscar(query):
    q = query.lower().strip()
    return [p for p in BASE if q in p["name"].lower() or q in (p.get("code") or "").lower()][:8]

def stock_emoji(p):
    s = p.get("stock", 0) or 0
    m = p.get("min", 0) or 0
    if s == 0: return "🔴"
    if s < m: return "🟡"
    return "🟢"

async def start(update: Update, ctx: ContextTypes.DEFAULT_TYPE):
    await update.message.reply_text(
        "🔧 Bodega San Carlos\n\n"
        "Escribe el nombre o código del repuesto que necesitas retirar.",
        parse_mode="Markdown"
    )

async def buscar_repuesto(update: Update, ctx: ContextTypes.DEFAULT_TYPE):
    uid = update.effective_user.id
    texto = update.message.text.strip()

    # Si está esperando cantidad
    if user_state.get(uid, {}).get("paso") == "cantidad":
        try:
            qty = int(texto)
            if qty < 1: raise ValueError()
            user_state[uid]["qty"] = qty
            user_state[uid]["paso"] = "nombre"
            p = user_state[uid]["repuesto"]
            await update.message.reply_text(
                f"✅ {qty} × {p['name']}\n\n¿Tu nombre?",
                parse_mode="Markdown"
            )
        except:
            await update.message.reply_text("Ingresa un número válido (ej: 2)")
        return

    # Si está esperando nombre
    if user_state.get(uid, {}).get("paso") == "nombre":
        nombre = texto
        p = user_state[uid]["repuesto"]
        qty = user_state[uid]["qty"]
        user_state.pop(uid, None)
        msg = (
            f"📦 RETIRO REGISTRADO\n"
            f"━━━━━━━━━━━━━━━\n"
            f"Repuesto: {p['name']}\n"
            f"Código: {p.get('code', 'sin código')}\n"
            f"Línea: {p.get('line', '–')}\n"
            f"Cantidad: {qty}\n"
            f"Técnico: {nombre}\n"
            f"━━━━━━━━━━━━━━━\n"
            f"Rubén confirmará el descuento en la app."
        )
        await update.message.reply_text(msg, parse_mode="Markdown")
        return

    # Búsqueda normal
    resultados = buscar(texto)
    if not resultados:
        await update.message.reply_text("No encontré ese repuesto. Intenta con otra palabra.")
        return

    keyboard = []
    for p in resultados:
        emoji = stock_emoji(p)
        label = f"{emoji} {p['name'][:40]} · {p.get('stock', '–')} un."
        keyboard.append([InlineKeyboardButton(label, callback_data=p["id"])])

    await update.message.reply_text(
        f"Encontré {len(resultados)} repuesto(s):",
        reply_markup=InlineKeyboardMarkup(keyboard)
    )

async def seleccionar(update: Update, ctx: ContextTypes.DEFAULT_TYPE):
    query = update.callback_query
    await query.answer()
    uid = query.from_user.id
    pid = query.data
    p = next((x for x in BASE if x["id"] == pid), None)
    if not p:
        await query.edit_message_text("Repuesto no encontrado.")
        return

    emoji = stock_emoji(p)
    s = p.get("stock", 0) or 0
    m = p.get("min", 0) or 0
    texto = (
        f"{emoji} {p['name']}\n"
        f"Código: {p.get('code', 'sin código')}\n"
        f"Línea: {p.get('line', '–')}\n"
        f"Stock: {s} · Mínimo: {m}\n\n"
    )
    if s == 0:
        texto += "⚠️ Sin stock. Avisa al supervisor.\n\n"
    texto += "¿Cuántas unidades retiras?"
    user_state[uid] = {"paso": "cantidad", "repuesto": p}
    await query.edit_message_text(texto, parse_mode="Markdown")

if _name_ == "_main_":
    app = ApplicationBuilder().token(TOKEN).build()
    app.add_handler(CommandHandler("start", start))
    app.add_handler(CallbackQueryHandler(seleccionar))
    app.add_handler(MessageHandler(filters.TEXT & ~filters.COMMAND, buscar_repuesto))
    print("Bot corriendo...")
    app.run_polling()
